import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Integer> nums = new ArrayList<>();
        nums.add(1);
        nums.add(5);
        nums.add(9);
        nums.remove(Integer.valueOf(1));
        System.out.println(nums);
    }
}
